{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError('case must be a dictionary')
    if 'nodes' not in case or 'required_symbols' not in case:
        raise ValueError('case is missing required fields')

    nodes = case['nodes']
    required_symbols = case['required_symbols']
    if not isinstance(nodes, list) or not nodes:
        raise ValueError('nodes must be a non-empty list')
    if not isinstance(required_symbols, list):
        raise ValueError('required_symbols must be a list')
    if any(not isinstance(symbol, str) for symbol in required_symbols):
        raise ValueError('required symbols must be strings')

    by_id = {}
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError('each node must be a dictionary')
        for field in ('id', 'parent', 'symbol', 'depth', 'removable', 'utility'):
            if field not in node:
                raise ValueError('node is missing required field: ' + field)
        node_id = node['id']
        if not isinstance(node_id, str) or not node_id:
            raise ValueError('node id must be a non-empty string')
        if node_id in by_id:
            raise ValueError('node ids must be unique')
        parent = node['parent']
        if parent is not None and (not isinstance(parent, str) or not parent):
            raise ValueError('parent must be null or a non-empty string')
        if not isinstance(node['symbol'], str):
            raise ValueError('symbol must be a string')
        if isinstance(node['depth'], bool) or not isinstance(node['depth'], int) or node['depth'] < 0:
            raise ValueError('depth must be a non-negative integer')
        if not isinstance(node['removable'], bool):
            raise ValueError('removable must be a boolean')
        utility = node['utility']
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError('utility must be a finite number')
        by_id[node_id] = node

    roots = []
    children = {node_id: set() for node_id in by_id}
    for node_id, node in by_id.items():
        parent = node['parent']
        if parent is None:
            if node['depth'] != 0:
                raise ValueError('root depth must be zero')
            roots.append(node_id)
        else:
            if parent not in by_id:
                raise ValueError('parent id is not registered')
            if parent == node_id:
                raise ValueError('node cannot parent itself')
            if node['depth'] != by_id[parent]['depth'] + 1:
                raise ValueError('node depth must follow its parent')
            children[parent].add(node_id)
    if len(roots) != 1:
        raise ValueError('tree must have exactly one root')

    for node_id in by_id:
        seen = set()
        current = node_id
        while by_id[current]['parent'] is not None:
            current = by_id[current]['parent']
            if current in seen:
                raise ValueError('tree contains a cycle')
            seen.add(current)

    required = set(required_symbols)
    represented = {node['symbol'] for node in by_id.values()}
    if not required.issubset(represented):
        raise ValueError('each required symbol must be represented')

    root_id = roots[0]
    candidate_order = sorted(
        (node_id for node_id, node in by_id.items() if node['removable'] and node_id != root_id),
        key=lambda node_id: (-by_id[node_id]['depth'], node_id),
    )

    retained = set(by_id)
    removal_order = []
    for node_id in candidate_order:
        node = by_id[node_id]
        if node['symbol'] in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue
        remaining_symbols = {by_id[other_id]['symbol'] for other_id in retained if other_id != node_id}
        if not required.issubset(remaining_symbols):
            continue
        retained.remove(node_id)
        removal_order.append(node_id)

    retained_ids = sorted(retained)
    grammar_valid = root_id in retained and all(
        node_id == root_id or node['parent'] in retained
        for node_id, node in by_id.items()
        if node_id in retained
    )
    interestingness_preserved = required.issubset({by_id[node_id]['symbol'] for node_id in retained})

    return {
        'retained_ids': retained_ids,
        'removal_order': removal_order,
        'grammar_valid': grammar_valid,
        'interestingness_preserved': interestingness_preserved,
        'registered_candidate_order': candidate_order,
        'stable_ties': True,
    }
"}
